    81→
    82→public(package) fun get_oracle_base_token(self: &EModeGroup): BaseToken { self.oracle_base_token }
    83→
    84→/// Add a new asset configuration into the emode registry
    85→public struct NewEMode has copy, drop, store {
    86→    collateral_factor: Decimal,
    87→    liquidation_factor: Decimal,
    88→    liquidation_incentive: Decimal,
    89→
    90→    max_borrow_amount: u64,
    91→    borrow_weight: Decimal,
