    98→
    99→public(package) fun new_emode_params(
   100→    collateral_factor: Decimal,
   101→    liquidation_factor: Decimal,
   102→    liquidation_incentive: Decimal,
   103→
   104→    max_borrow_amount: u64,
   105→    borrow_weight: Decimal,
   106→
   107→    flash_loan_fee_rate: Decimal,
   108→
   109→    deposit_limiter: NewLimiter,
   110→    borrow_limiter: NewLimiter,
   111→): NewEMode {
   112→    NewEMode {
   113→        collateral_factor,
   114→        liquidation_factor,
   115→        liquidation_incentive,
   116→
   117→        max_borrow_amount,
   118→        borrow_weight,
   119→
   120→        flash_loan_fee_rate,
   121→
   122→        deposit_limiter,
   123→        borrow_limiter,
   124→    }
   125→}
   126→
   127→public(package) fun borrow_emode_group_mut(registry: &mut EModeGroupRegistry, group: u8): &mut EModeGroup {
   128→    registry.ensure_group_exists(group);
   129→    registry.groups.borrow_mut(group)
   130→}
   131→
   132→public(package) fun support_asset<CoinType>(registry: &mut EModeGroupRegistry, group: u8, params: NewEMode, ctx: &mut TxContext) {
   133→    assert!(registry.groups.contains(group), error::emode_group_not_exists());
   134→
   135→    let group = registry.groups.borrow_mut(group);
   136→    assert!(!group.assets.supports<EMode, CoinType>(), error::emode_group_already_supports_asset());
   137→
   138→    let mut emode = EMode { id: object::new(ctx) };
   139→
   140→    let NewEMode {
   141→        collateral_factor,
   142→        liquidation_factor,
   143→        liquidation_incentive,
   144→
   145→        max_borrow_amount,
   146→        borrow_weight,
   147→
   148→        flash_loan_fee_rate,
   149→
   150→        deposit_limiter,
   151→        borrow_limiter,
   152→    } = params;
   153→
   154→    let collateral = EModeCollateral {
   155→        collateral_factor: collateral_factor,
   156→        liquidation_factor: liquidation_factor,
   157→        liquidation_incentive: liquidation_incentive,
   158→    };
   159→
   160→    dynamic_field::add(&mut emode.id, DFKey<EModeCollateral> {}, collateral);
   161→
   162→    let borrow = EModeBorrow {
   163→        max_borrow_amount: max_borrow_amount,
   164→        borrow_weight: borrow_weight,
   165→    };
   166→    dynamic_field::add(&mut emode.id, DFKey<EModeBorrow> {}, borrow);
   167→
   168→    let flashloan = EModeFlashLoan {
   169→        flash_loan_fee_rate: flash_loan_fee_rate,
   170→    };
   171→    dynamic_field::add(&mut emode.id, DFKey<EModeFlashLoan> {}, flashloan);
   172→
   173→    let limiter = EModeRateLimiter {
   174→        deposit: limiter::new_from_struct(deposit_limiter),
   175→        borrow: limiter::new_from_struct(borrow_limiter),
   176→    };
   177→    dynamic_field::add(&mut emode.id, DFKey<EModeRateLimiter> {}, limiter);
   178→
   179→    group.assets.store<EMode, CoinType>(emode);
   180→    group.assets_borrows.store<Decimal, CoinType>(math::float::zero());
   181→}
   182→
   183→public(package) fun update_asset_borrow(self: &mut EModeGroup, coin: TypeName, old_value: Decimal, new_value: Decimal): Decimal {
   184→    assert!(self.assets_borrows.supports_type(coin), error::emode_group_does_not_support_asset());
   185→
   186→    let current_borrow = self.assets_borrows.load_mut_by_type(coin);
   187→    // using saturating_sub, if the value is below 0, just let it be zero
   188→    let new_borrow = new_value.add(*current_borrow).saturating_sub(old_value);
   189→
   190→    *current_borrow = new_borrow;
   191→    new_borrow
   192→}
   193→
   194→public(package) fun borrow_amount(self: &EModeGroup, coin: TypeName): Decimal {
   195→    assert!(self.assets_borrows.supports_type(coin), error::emode_group_does_not_support_asset());
   196→    *self.assets_borrows.load_by_type(coin)
   197→}
   198→
   199→public(package) fun update_collateral(
   200→    self: &mut EMode,
   201→
   202→    collateral_factor: Decimal,
   203→    liquidation_factor: Decimal,
   204→    liquidation_incentive: Decimal,
   205→) {
   206→    let c = dynamic_field::borrow_mut<DFKey<EModeCollateral>, EModeCollateral>(
   207→        &mut self.id,
   208→        DFKey<EModeCollateral> {},
   209→    );
   210→    c.collateral_factor = collateral_factor;
   211→    c.liquidation_factor = liquidation_factor;
   212→    c.liquidation_incentive = liquidation_incentive;
   213→}
   214→
   215→public(package) fun update_borrow(
   216→    self: &mut EMode,
   217→
   218→    max_borrow_amount: u64,
   219→    borrow_weight: Decimal,
   220→) {
