   222→        &mut self.id,
   223→        DFKey<EModeBorrow> {},
   224→    );
   225→    c.max_borrow_amount = max_borrow_amount;
   226→    c.borrow_weight = borrow_weight;
   227→}
   228→
   229→public(package) fun update_limiter(
   230→    self: &mut EMode,
   231→
   232→    deposit_limiter: NewLimiter,
   233→    borrow_limiter: NewLimiter,
   234→) {
   235→    let c = dynamic_field::borrow_mut<DFKey<EModeRateLimiter>, EModeRateLimiter>(
   236→        &mut self.id,
   237→        DFKey<EModeRateLimiter> {},
