   480→        float::from_quotient(1, 1000),  // flash_loan_fee_rate: 0.001
   481→        limiter::create_new_limiter_change(5000000000, 86400, 3600), // deposit_limiter: 5B per day, 1hr segments
   482→        limiter::create_new_limiter_change(2000000000, 86400, 3600), // borrow_limiter: 2B per day, 1hr segments
   483→    );
   484→
   485→    // Create params for TestCoinB in group2 with DIFFERENT values
   486→    let params_b_g2 = new_emode_params(
