module protocol::emode;

use std::type_name::TypeName;

use sui::table::{Self, Table};
use sui::dynamic_field;

use math::float::Decimal;
use protocol::generic_store::{Self, GenericCoinTypeStorage};
use protocol::error;
use x_oracle::x_oracle::{Self, BaseToken};
use protocol::limiter::{Self, Limiter, NewLimiter};
use protocol::limiter::RateLimitUsage;

public struct EModeCollateral has store {
    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,
}

public struct EModeBorrow has store {
    max_borrow_amount: u64,
    borrow_weight: Decimal,
}

public struct EModeFlashLoan has store {
    flash_loan_fee_rate: Decimal,
}

public struct EModeRateLimiter has store {
    deposit: Limiter,
    borrow: Limiter,
}

public struct EMode has key, store {
    id: UID,

    // dynamic fields:
    // - collateral: EModeCollateral,
    // - borrow: EModeBorrow,
    // - flashloan: EModeFlashLoan,
    // - limiter: EModeRateLimiter,
}

public struct EModeGroup has store {
    assets: GenericCoinTypeStorage<EMode>,
    assets_borrows: GenericCoinTypeStorage<Decimal>,
    oracle_base_token: BaseToken,
}

public struct EModeGroupRegistry has store {
    next_group_id: u8,
    groups: Table<u8, EModeGroup>,
}

public(package) fun new_e_mode_registry(ctx: &mut TxContext): EModeGroupRegistry {
    EModeGroupRegistry {
        next_group_id: 0,
        groups: table::new(ctx)
    }
}

/// Create a new e mode group and returns the e mode id
public(package) fun new_emode_group(registry: &mut EModeGroupRegistry, oracle_base_token: u8, ctx: &mut TxContext): u8 {
    let next_id = registry.next_group_id;
    assert!(next_id != std::u8::max_value!(), error::max_emode_groups_reached());

    registry.next_group_id = registry.next_group_id + 1;

    registry.groups.add(
        next_id,
        EModeGroup {
            oracle_base_token: x_oracle::base_token_from_u8(oracle_base_token),
            assets_borrows: generic_store::new<Decimal>(ctx),
            assets: generic_store::new<EMode>(ctx)
        }
    );

    next_id
}

public(package) fun get_oracle_base_token(self: &EModeGroup): BaseToken { self.oracle_base_token }

/// Add a new asset configuration into the emode registry
public struct NewEMode has copy, drop, store {
    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,

    max_borrow_amount: u64,
    borrow_weight: Decimal,

    flash_loan_fee_rate: Decimal,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
}

public(package) fun new_emode_params(
    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,

    max_borrow_amount: u64,
    borrow_weight: Decimal,

    flash_loan_fee_rate: Decimal,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
): NewEMode {
    NewEMode {
        collateral_factor,
        liquidation_factor,
        liquidation_incentive,

        max_borrow_amount,
        borrow_weight,

        flash_loan_fee_rate,

        deposit_limiter,
        borrow_limiter,
    }
}

public(package) fun borrow_emode_group_mut(registry: &mut EModeGroupRegistry, group: u8): &mut EModeGroup {
    registry.ensure_group_exists(group);
    registry.groups.borrow_mut(group)
}

public(package) fun support_asset<CoinType>(registry: &mut EModeGroupRegistry, group: u8, params: NewEMode, ctx: &mut TxContext) {
    assert!(registry.groups.contains(group), error::emode_group_not_exists());

    let group = registry.groups.borrow_mut(group);
    assert!(!group.assets.supports<EMode, CoinType>(), error::emode_group_already_supports_asset());

    let mut emode = EMode { id: object::new(ctx) };

    let NewEMode {
        collateral_factor,
        liquidation_factor,
        liquidation_incentive,

        max_borrow_amount,
        borrow_weight,

        flash_loan_fee_rate,

        deposit_limiter,
        borrow_limiter,
    } = params;

    let collateral = EModeCollateral {
        collateral_factor: collateral_factor,
        liquidation_factor: liquidation_factor,
        liquidation_incentive: liquidation_incentive,
    };

    dynamic_field::add(&mut emode.id, DFKey<EModeCollateral> {}, collateral);

    let borrow = EModeBorrow {
        max_borrow_amount: max_borrow_amount,
        borrow_weight: borrow_weight,
    };
    dynamic_field::add(&mut emode.id, DFKey<EModeBorrow> {}, borrow);

    let flashloan = EModeFlashLoan {
        flash_loan_fee_rate: flash_loan_fee_rate,
    };
    dynamic_field::add(&mut emode.id, DFKey<EModeFlashLoan> {}, flashloan);

    let limiter = EModeRateLimiter {
        deposit: limiter::new_from_struct(deposit_limiter),
        borrow: limiter::new_from_struct(borrow_limiter),
    };
    dynamic_field::add(&mut emode.id, DFKey<EModeRateLimiter> {}, limiter);

    group.assets.store<EMode, CoinType>(emode);
    group.assets_borrows.store<Decimal, CoinType>(math::float::zero());
}

public(package) fun update_asset_borrow(self: &mut EModeGroup, coin: TypeName, old_value: Decimal, new_value: Decimal): Decimal {
    assert!(self.assets_borrows.supports_type(coin), error::emode_group_does_not_support_asset());

    let current_borrow = self.assets_borrows.load_mut_by_type(coin);
    // using saturating_sub, if the value is below 0, just let it be zero
    let new_borrow = new_value.add(*current_borrow).saturating_sub(old_value);

    *current_borrow = new_borrow;
    new_borrow
}

public(package) fun borrow_amount(self: &EModeGroup, coin: TypeName): Decimal {
    assert!(self.assets_borrows.supports_type(coin), error::emode_group_does_not_support_asset());
    *self.assets_borrows.load_by_type(coin)
}

public(package) fun update_collateral(
    self: &mut EMode,

    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,
) {
    let c = dynamic_field::borrow_mut<DFKey<EModeCollateral>, EModeCollateral>(
        &mut self.id,
        DFKey<EModeCollateral> {},
    );
    c.collateral_factor = collateral_factor;
    c.liquidation_factor = liquidation_factor;
    c.liquidation_incentive = liquidation_incentive;
}

public(package) fun update_borrow(
    self: &mut EMode,

    max_borrow_amount: u64,
    borrow_weight: Decimal,
) {
    let c = dynamic_field::borrow_mut<DFKey<EModeBorrow>, EModeBorrow>(
        &mut self.id,
        DFKey<EModeBorrow> {},
    );
    c.max_borrow_amount = max_borrow_amount;
    c.borrow_weight = borrow_weight;
}

public(package) fun update_limiter(
    self: &mut EMode,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
) {
    let c = dynamic_field::borrow_mut<DFKey<EModeRateLimiter>, EModeRateLimiter>(
        &mut self.id,
        DFKey<EModeRateLimiter> {},
    );

    c.deposit = limiter::new_from_struct(deposit_limiter);
    c.borrow = limiter::new_from_struct(borrow_limiter);
}

public(package) fun update_flash_loan(
    self: &mut EMode,
    flash_loan_fee_rate: Decimal,
) {
    let c = dynamic_field::borrow_mut<DFKey<EModeFlashLoan>, EModeFlashLoan>(
        &mut self.id,
        DFKey<EModeFlashLoan> {},
    );
    c.flash_loan_fee_rate = flash_loan_fee_rate;
}

public(package) fun borrow_mut_deposit_limiter(self: &mut EMode): &mut Limiter {
    let c = dynamic_field::borrow_mut<DFKey<EModeRateLimiter>, EModeRateLimiter>(
        &mut self.id,
        DFKey<EModeRateLimiter> {},
    );
    &mut c.deposit
}

public(package) fun borrow_mut_borrow_limiter(self: &mut EMode): &mut Limiter {
    let c = dynamic_field::borrow_mut<DFKey<EModeRateLimiter>, EModeRateLimiter>(
        &mut self.id,
        DFKey<EModeRateLimiter> {},
    );
    &mut c.borrow
}

public(package) fun borrow_mut_emode(registry: &mut EModeGroupRegistry, group: u8, asset: TypeName): &mut EMode {
    registry.ensure_group_exists(group);

    let group = registry.groups.borrow_mut(group);
    assert!(group.assets.supports_type(asset), error::emode_group_does_not_support_asset());

    group.assets.load_mut_by_type(asset)
}

public(package) fun update(emode: &mut EMode, params: NewEMode) {
    let NewEMode {
        collateral_factor,
        liquidation_factor,
        liquidation_incentive,

        max_borrow_amount,
        borrow_weight,

        flash_loan_fee_rate,

        deposit_limiter,
        borrow_limiter,
    } = params;


    let collateral: &mut EModeCollateral = dynamic_field::borrow_mut(&mut emode.id, DFKey<EModeCollateral> {});
    collateral.collateral_factor = collateral_factor;
    collateral.liquidation_factor = liquidation_factor;
    collateral.liquidation_incentive = liquidation_incentive;

    let borrow: &mut EModeBorrow = dynamic_field::borrow_mut(&mut emode.id, DFKey<EModeBorrow> {});
    borrow.max_borrow_amount = max_borrow_amount;
    borrow.borrow_weight = borrow_weight;

    let flashloan: &mut EModeFlashLoan = dynamic_field::borrow_mut(&mut emode.id, DFKey<EModeFlashLoan> {});
    flashloan.flash_loan_fee_rate = flash_loan_fee_rate;

    let limiter: &mut EModeRateLimiter = dynamic_field::borrow_mut(&mut emode.id, DFKey<EModeRateLimiter> {});
    limiter.deposit = limiter::new_from_struct(deposit_limiter);
    limiter.borrow = limiter::new_from_struct(borrow_limiter);
}

/// ================= Public GETTERS ================
public struct EModeInfo has copy, drop {
    asset: TypeName,
    oracle_base_token: BaseToken,

    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,

    max_borrow_amount: u64,
    borrow_weight: Decimal,

    flash_loan_fee_rate: Decimal,

    deposit_limiter: RateLimitUsage,
    borrow_limiter: RateLimitUsage,
}

public(package) fun ensure_group_exists(self: &EModeGroupRegistry, group: u8) {
    assert!(self.groups.contains(group), error::emode_group_not_exists());
}

public fun list_assets(registry: &EModeGroupRegistry, group: u8, now: u64): vector<EModeInfo> {
    registry.ensure_group_exists(group);

    let group = registry.groups.borrow(group);

    let oracle_base_token = group.get_oracle_base_token();
    let assets = group.assets.keys();

    let (mut i, n) = (0, assets.length());

    let mut results = vector::empty<EModeInfo>();
    while (i < n) {
        let emode = group.assets.load_by_type(*assets.borrow(i));
        let (deposit_limiter, borrow_limiter) = emode.limiter_usage(now);

        results.push_back(
            EModeInfo {
                asset: *assets.borrow(i),
                oracle_base_token,
                collateral_factor: emode.collateral().collateral_factor(),
                liquidation_factor: emode.collateral().liquidation_factor(),
                liquidation_incentive: emode.collateral().liquidation_incentive(),
                max_borrow_amount: emode.borrow().max_borrow_amount(),
                borrow_weight: emode.borrow().borrow_weight(),
                flash_loan_fee_rate: emode.flash_loan().fee_rate(),
                deposit_limiter,
                borrow_limiter,
            }
        );
        i = i + 1;
    };

    results
}

public(package) fun borrow_emode_group(registry: &EModeGroupRegistry, group: u8): &EModeGroup {
    registry.ensure_group_exists(group);
    registry.groups.borrow(group)
}

public(package) fun borrow_emode(self: &EModeGroup, asset: TypeName): &EMode {
    assert!(self.assets.supports_type(asset), error::emode_group_does_not_support_asset());
    self.assets.load_by_type(asset)
}

public(package) fun borrow_emode_mut(self: &mut EModeGroup, asset: TypeName): &mut EMode {
    assert!(self.assets.supports_type(asset), error::emode_group_does_not_support_asset());
    self.assets.load_mut_by_type(asset)
}

public(package) fun collateral(self: &EMode): &EModeCollateral { dynamic_field::borrow<DFKey<EModeCollateral>, EModeCollateral>(&self.id, DFKey<EModeCollateral> {}) }
public(package) fun collateral_factor(self: &EModeCollateral): Decimal { self.collateral_factor }
public(package) fun liquidation_factor(self: &EModeCollateral): Decimal { self.liquidation_factor }
public(package) fun liquidation_incentive(self: &EModeCollateral): Decimal { self.liquidation_incentive }
public(package) fun borrow(self: &EMode): &EModeBorrow { dynamic_field::borrow<DFKey<EModeBorrow>, EModeBorrow>(&self.id, DFKey<EModeBorrow> {}) }
public(package) fun max_borrow_amount(self: &EModeBorrow): u64 { self.max_borrow_amount }
public(package) fun borrow_weight(self: &EModeBorrow): Decimal { self.borrow_weight }
public(package) fun flash_loan(self: &EMode): &EModeFlashLoan { dynamic_field::borrow<DFKey<EModeFlashLoan>, EModeFlashLoan>(&self.id, DFKey<EModeFlashLoan> {}) }
public(package) fun fee_rate(self: &EModeFlashLoan): Decimal { self.flash_loan_fee_rate }

public(package) fun limiter_usage(self: &EMode, now: u64): (RateLimitUsage, RateLimitUsage) {
    let limiter = dynamic_field::borrow<DFKey<EModeRateLimiter>, EModeRateLimiter>(&self.id, DFKey<EModeRateLimiter> {});
    (limiter.deposit.current_usage(now), limiter.borrow.current_usage(now))
}

public(package) fun can_be_collateral(self: &EModeCollateral): bool {
    self.liquidation_factor().gt_u64(0)
}

public struct DFKey<phantom T> has copy, drop, store {}

// ================= TESTS =================

#[test_only]
public fun get_asset_borrow(registry: &EModeGroupRegistry, group: u8, asset: TypeName): u64 {
    registry.ensure_group_exists(group);
    let group = registry.groups.borrow(group);
    (*group.assets_borrows.load_by_type(asset)).ceil()
}

#[test_only]
public(package) fun is_support(registry: &EModeGroupRegistry, group: u8, asset: TypeName): bool {
    registry.ensure_group_exists(group);
    registry.groups.borrow(group).assets.supports_type(asset)
}

#[test_only]
public struct TestCoinA has drop {}

#[test_only]
public struct TestCoinB has drop {}

#[test]
fun test_new_emode_group() {
    use sui::test_scenario;

    let mut scenario = test_scenario::begin(@0x1);
    let ctx = scenario.ctx();

    let mut registry = new_e_mode_registry(ctx);

    // init condition is correct
    assert!(registry.next_group_id == 0, 0);
    assert!(!registry.groups.contains(0), 1);

    // Create a new emode group
    let group1 = registry.new_emode_group(0, scenario.ctx());
    assert!(group1 == 0, 2);
    assert!(registry.next_group_id == 1, 3);
    assert!(registry.groups.contains(0), 4);

    // Create another emode group
    let group2 = registry.new_emode_group(0, scenario.ctx());
    assert!(group2 == 1, 5);
    assert!(registry.next_group_id == 2, 6);
    assert!(registry.groups.contains(1), 7);

    scenario.end();
    std::unit_test::destroy(registry);
}

#[test]
fun test_support_asset_two_groups() {
    use sui::test_scenario;
    use math::float;

    let mut scenario = test_scenario::begin(@0x1);
    let ctx = scenario.ctx();

    let mut registry = new_e_mode_registry(ctx);

    // Create two emode groups
    let group1 = registry.new_emode_group(0, scenario.ctx());
    let group2 = registry.new_emode_group(0, scenario.ctx());

    assert!(group1 == 0, 0);
    assert!(group2 == 1, 1);

    // Create params for TestCoinA in group1
    let params_a_g1 = new_emode_params(
        float::from_quotient(80, 100),  // collateral_factor: 0.8
        float::from_quotient(85, 100),  // liquidation_factor: 0.85
        float::from_quotient(5, 100),   // liquidation_incentive: 0.05
        1000000000,                      // max_borrow_amount: 1B
        float::from_quotient(110, 100), // borrow_weight: 1.1
        float::from_quotient(1, 1000),  // flash_loan_fee_rate: 0.001
        limiter::create_new_limiter_change(5000000000, 86400, 3600), // deposit_limiter: 5B per day, 1hr segments
        limiter::create_new_limiter_change(2000000000, 86400, 3600), // borrow_limiter: 2B per day, 1hr segments
    );

    // Create params for TestCoinB in group2 with DIFFERENT values
    let params_b_g2 = new_emode_params(
        float::from_quotient(70, 100),  // collateral_factor: 0.7 (different)
        float::from_quotient(75, 100),  // liquidation_factor: 0.75 (different)
        float::from_quotient(10, 100),  // liquidation_incentive: 0.10 (different)
        500000000,                       // max_borrow_amount: 500M (different)
        float::from_quotient(120, 100), // borrow_weight: 1.2 (different)
        float::from_quotient(2, 1000),  // flash_loan_fee_rate: 0.002 (different)
        limiter::create_new_limiter_change(3000000000, 86400, 3600), // deposit_limiter: 3B per day (different)
        limiter::create_new_limiter_change(1000000000, 86400, 3600), // borrow_limiter: 1B per day (different)
    );

    // Support assets in different groups
    registry.support_asset<TestCoinA>(group1, params_a_g1, scenario.ctx());
    registry.support_asset<TestCoinB>(group2, params_b_g2, scenario.ctx());

    // Verify TestCoinA in group1
    let type_name_a = std::type_name::with_defining_ids<TestCoinA>();
    assert!(registry.is_support(group1, type_name_a), 2);
    let emode_a = registry.borrow_emode_group(group1).borrow_emode(type_name_a);

    let collateral_a = emode_a.collateral();
    assert!(collateral_a.collateral_factor().eq(float::from_quotient(80, 100)), 3);
    assert!(collateral_a.liquidation_factor().eq(float::from_quotient(85, 100)), 4);
    assert!(collateral_a.liquidation_incentive().eq(float::from_quotient(5, 100)), 5);

    let borrow_a = emode_a.borrow();
    assert!(borrow_a.max_borrow_amount() == 1000000000, 6);
    assert!(borrow_a.borrow_weight().eq(float::from_quotient(110, 100)), 7);

    let flashloan_a = emode_a.flash_loan();
    assert!(flashloan_a.fee_rate().eq(float::from_quotient(1, 1000)), 8);

    // Verify TestCoinB in group2 has DIFFERENT values
    let type_name_b = std::type_name::with_defining_ids<TestCoinB>();
    assert!(registry.is_support(group2, type_name_b), 9);
    let emode_b = registry.borrow_emode_group(group2).borrow_emode(type_name_b);

    let collateral_b = emode_b.collateral();
    assert!(collateral_b.collateral_factor().eq(float::from_quotient(70, 100)), 10);
    assert!(collateral_b.liquidation_factor().eq(float::from_quotient(75, 100)), 11);
    assert!(collateral_b.liquidation_incentive().eq(float::from_quotient(10, 100)), 12);

    let borrow_b = emode_b.borrow();
    assert!(borrow_b.max_borrow_amount() == 500000000, 13);
    assert!(borrow_b.borrow_weight().eq(float::from_quotient(120, 100)), 14);

    let flashloan_b = emode_b.flash_loan();
    assert!(flashloan_b.fee_rate().eq(float::from_quotient(2, 1000)), 15);

    // Verify that values are indeed different between groups
    assert!(!collateral_a.collateral_factor().eq(collateral_b.collateral_factor()), 16);
    assert!(!collateral_a.liquidation_factor().eq(collateral_b.liquidation_factor()), 17);
    assert!(!collateral_a.liquidation_incentive().eq(collateral_b.liquidation_incentive()), 18);
    assert!(borrow_a.max_borrow_amount() != borrow_b.max_borrow_amount(), 19);
    assert!(!borrow_a.borrow_weight().eq(borrow_b.borrow_weight()), 20);
    assert!(!flashloan_a.fee_rate().eq(flashloan_b.fee_rate()), 21);

    // Verify TestCoinA is NOT in group2 and TestCoinB is NOT in group1
    assert!(!registry.is_support(group2, type_name_a), 22);
    assert!(!registry.is_support(group1, type_name_b), 23);

    scenario.end();
    std::unit_test::destroy(registry);
}

#[test]
fun test_update_collateral() {
    use sui::test_scenario;
    use math::float;

    let mut scenario = test_scenario::begin(@0x1);
    let ctx = scenario.ctx();

    let mut registry = new_e_mode_registry(ctx);
    let group1 = registry.new_emode_group(0, scenario.ctx());

    // Create and support asset
    let params = new_emode_params(
        float::from_quotient(80, 100),
        float::from_quotient(85, 100),
        float::from_quotient(5, 100),
