fun test_update_limiter() {
    use sui::test_scenario;
    use math::float;

    let mut scenario = test_scenario::begin(@0x1);
    let ctx = scenario.ctx();

    let mut registry = new_e_mode_registry(ctx);
    let group1 = registry.new_emode_group(0, scenario.ctx());

    // Create and support asset with initial limiters
    let params = new_emode_params(
        float::from_quotient(80, 100),
        float::from_quotient(85, 100),
        float::from_quotient(5, 100),
        1000000000,
        float::from_quotient(110, 100),
        float::from_quotient(1, 1000),
        limiter::create_new_limiter_change(5000000000, 86400, 3600), // 5B per day
        limiter::create_new_limiter_change(2000000000, 86400, 3600), // 2B per day
    );

    registry.support_asset<TestCoinA>(group1, params, scenario.ctx());

    // Verify initial limiter values
    let type_name_a = std::type_name::with_defining_ids<TestCoinA>();
    let emode = registry.borrow_emode_group(group1).borrow_emode(type_name_a);
    let (deposit_usage_before, borrow_usage_before) = emode.limiter_usage(1000);

    // Check initial limits are correct
    assert!(deposit_usage_before.limit() == 5000000000, 0);
    assert!(borrow_usage_before.limit() == 2000000000, 1);
    assert!(deposit_usage_before.usage() == 0, 2);
    assert!(borrow_usage_before.usage() == 0, 3);

    // Get mutable reference and update limiters
    let emode_mut = registry.borrow_mut_emode(group1, type_name_a);
    emode_mut.update_limiter(
        limiter::create_new_limiter_change(10000000000, 86400, 3600), // new deposit: 10B per day
        limiter::create_new_limiter_change(4000000000, 86400, 3600),  // new borrow: 4B per day
    );

    // Verify updates by checking limiter usage with updated limits
    let (deposit_usage_after, borrow_usage_after) = emode_mut.limiter_usage(1000);

    // Validate the new limits
    assert!(deposit_usage_after.limit() == 10000000000, 4);
    assert!(borrow_usage_after.limit() == 4000000000, 5);
    assert!(deposit_usage_after.usage() == 0, 6);
    assert!(borrow_usage_after.usage() == 0, 7);

    scenario.end();
    std::unit_test::destroy(registry);
}

